INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(7601, '2 Samuel 3:31', '2 Samuel', 3, 31, '&nbsp;بيا داؤد يوآب او د هغۀ سړو له حُکم ورکړو چې خپلې جامې وشلوئ، د ټاټ جامې واغوندئ او په ابنير ماتم وکړئ. او د جنازې سره داؤد بادشاه په خپله د تابوت نه وروستو روان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7602, '2 Samuel 3:32', '2 Samuel', 3, 32, '&nbsp;ابنير په حبرون کښې ښخ شو او بادشاه په چغو چغو د قبر سره وژړل او ټولو خلقو هم وژړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7603, '2 Samuel 3:33', '2 Samuel', 3, 33, '&nbsp;داؤد د ابنير دپاره دا د غم سندره ووئيله، ”ابنير دې د يو کم عقل په شان ولې مړ شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7604, '2 Samuel 3:34', '2 Samuel', 3, 34, '&nbsp;ستا لاسونه نۀ وُو تړلى، او ستا پښې نۀ وې تړلې، تۀ داسې مړ شو لکه چې چا مجرم وژلے وى.“ او خلقو د هغۀ دپاره بيا وژړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7605, '2 Samuel 3:35', '2 Samuel', 3, 35, '&nbsp;ټوله ورځ خلقو کوشش کولو چې په داؤد باندې څۀ وخورى، خو هغۀ پوخ لوظ وکړو، ”خُدائ پاک دې ما هلاک کړى چې د ورځې د ختمېدو نه مخکښې زۀ څۀ وخورم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7606, '2 Samuel 3:36', '2 Samuel', 3, 36, '&nbsp;نو خلقو ته پته ولګېده او خوشحاله شول. په حقيقت کښې بادشاه چې څۀ هم کول نو خلق ترې نه خوشحالېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7607, '2 Samuel 3:37', '2 Samuel', 3, 37, '&nbsp;د داؤد او د بنى اِسرائيل ټولو خلقو ته دا پته ولګېده چې بادشاه د ابنير په وژلو کښې هيڅ برخه نۀ ده اخستې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7608, '2 Samuel 3:38', '2 Samuel', 3, 38, '&nbsp;بادشاه خپلو درباريانو ته ووئيل، ”تاسو ته پته نۀ لګى چې نن په بنى اِسرائيلو کښې يو لوئ مشر مړ شوے دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7609, '2 Samuel 3:39', '2 Samuel', 3, 39, '&nbsp;اګر چې زۀ بيا هم هغه بادشاه يم چې خُدائ پاک خوښ کړے يم، نن زۀ خپل ځان کمزورے ګڼم او د ضروياه دا زامن قابو کولے نۀ شم. مالِک خُدائ دې، دې مجرمانو له سزا ورکړى لکه چې څنګه دوئ د سزا حقدار دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7610, '2 Samuel 4:1', '2 Samuel', 4, 1, '&nbsp;کله چې د ساؤل زوئ اشبوست دا واورېدل چې ابنير په حبرون کښې قتل شوے دے، نو هغۀ خپله حوصله بائيله او ټول بنى اِسرائيليان ويرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7611, '2 Samuel 4:2', '2 Samuel', 4, 2, '&nbsp;د اشبوست دوه آفسران وُو کوم چې د لښکرو مشران وُو، د هغوئ نومونه بعنه او ريکاب وُو، هغوئ د رِمون زامن وُو چې هغه د بنيامين د قبيلې د بيروت نه وو. بيروت د بنيامين حِصه ګڼلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7612, '2 Samuel 4:3', '2 Samuel', 4, 3, '&nbsp;د دې اصلى اوسېدونکى جيتم ته تښتېدلى وُو چرته چې هغوئ تر نن ورځې پورې د مسافرو په شان اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7613, '2 Samuel 4:4', '2 Samuel', 4, 4, '&nbsp;د ساؤل بل اولاد د يونتن زوئ مفيبوست په پښو شل وو، هغه د پينځو کالو وو چې ساؤل او يونتن قتل شو. کله چې د يزرعيل ښار نه د هغوئ د مرګ خبر راورسېدو، نو د هغۀ دايڼې هغه واخستلو او وتښتېدله، خو هغه دومره په تېزۍ کښې وه چې هغه يې وغورزولو او هغه شل شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7614, '2 Samuel 4:5', '2 Samuel', 4, 5, '&nbsp;ريکاب او بعنه د اشبوست کور ته روان شول او په سره غرمه کښې هلته ورسېدل، هغۀ په دې وخت د غرمې آرام کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7615, '2 Samuel 4:6', '2 Samuel', 4, 6, '&nbsp;کله چې هغه څوکيدارې ښځې غنم صفا کول نو هغه خوبَولې شوه او اوده شوه، نو ريکاب او بعنه پټ دننه لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7616, '2 Samuel 4:7', '2 Samuel', 4, 7, '&nbsp;هغوئ سمدستى د اشبوست کوټې ته دننه لاړل، هلته هغه په خپل کټ کښې ملاست وو او هغوئ ووژلو. بيا هغوئ د هغۀ سر پرې کړو، د ځان سره يې يوړو او په هغه ټوله شپه يې د اُردن په وادۍ کښې مزل وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7617, '2 Samuel 4:8', '2 Samuel', 4, 8, '&nbsp;هغوئ د هغۀ سر په حبرون کښې داؤد بادشاه ته پېش کړو او ورته يې ووئيل، ”ستا د دشمن د ساؤل زوئ اشبوست سر دا دے، چا چې ستا د وژلو کوشش کړے وو. بادشاه سلامت، نن مالِک خُدائ تۀ پرېښے يې چې د ساؤل او د هغۀ د اولاد نه بدل واخلې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7618, '2 Samuel 4:9', '2 Samuel', 4, 9, '&nbsp;داؤد هغوئ ته وفرمائيل، ”زۀ په ژوندى مالِک خُدائ قسم خورم، چې هغۀ زۀ د ټولو خطرو نه بچ کړے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7619, '2 Samuel 4:10', '2 Samuel', 4, 10, '&nbsp;کوم پېغام وړونکے چې په صِقلاج کښې ما له راغلو او د ساؤل د مرګ نه يې خبر کړم د هغۀ خيال دا وو چې ګنې هغۀ يو زېرے راوړے دے خو هغه ما ونيولو او ومې وژلو. هغۀ له ما په زېرى کښې داسې اِنعام ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7620, '2 Samuel 4:11', '2 Samuel', 4, 11, '&nbsp;تاسو بدعمله سړو د هغۀ نه هم زيات بد عمل کړے دے چې د هغۀ په خپل کور کښې يو بې‌ګناه سړے مو په اودو وژلے دے. اوس به زۀ ستاسو نه د هغۀ د وژلو بدله واخلم او زۀ به تاسو د زمکې د مخ نه لرې کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7621, '2 Samuel 4:12', '2 Samuel', 4, 12, '&nbsp;نو داؤد حُکم وکړو او د هغۀ فوجيانو ريکاب او بعنه ووژل او د هغوئ لاسونه او پښې يې پرې کړې، هغوئ دا په حبرون کښې د تالاب سره نزدې راځوړند کړل. هغوئ د اشبوست سر واخستلو او هلته په حبرون کښې يې د ابنير په قبر کښې ښخ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7622, '2 Samuel 5:1', '2 Samuel', 5, 1, '&nbsp;بيا په حبرون کښې د بنى اِسرائيل ټولې قبيلې داؤد ته راغلې او هغۀ ته يې ووئيل، ”مونږ ستا خپله وينه يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7623, '2 Samuel 5:2', '2 Samuel', 5, 2, '&nbsp;په تېره زمانه کښې، ترڅو چې ساؤل زمونږ بادشاه وو نو تا په جنګ کښې د بنى اِسرائيلو مشرى کوله او مالِک خُدائ تا ته وفرمائيل چې تۀ به د هغۀ د خلقو مشرى کوې او د هغوئ بادشاه به يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7624, '2 Samuel 5:3', '2 Samuel', 5, 3, '&nbsp;نو د بنى اِسرائيل ټول مشران په حبرون کښې داؤد بادشاه له راغلل. داؤد د هغوئ سره لوظ وکړو، هغوئ د هغۀ سر په تېلو غوړ کړو، نو هغه د بنى اِسرائيلو بادشاه شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7625, '2 Samuel 5:4', '2 Samuel', 5, 4, '&nbsp;داؤد د دېرشو کالو وو چې هغه بادشاه شو او هغۀ څلوېښت کاله بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7626, '2 Samuel 5:5', '2 Samuel', 5, 5, '&nbsp;هغۀ په حبرون کښې په يهوداه باندې اووۀ نيم کاله بادشاهى وکړه او په يروشلم کښې يې په ټول اِسرائيل او يهوداه باندې درې دېرش کاله بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7627, '2 Samuel 5:6', '2 Samuel', 5, 6, '&nbsp;هغه وخت راغلو چې داؤد بادشاه او د هغۀ سړى په يروشلم باندې حملې کولو دپاره روان شول. کوم يبوسيان چې هلته اوسېدل د هغوئ خيال دا وو چې داؤد به ښار فتح نۀ کړى، نو هغوئ هغۀ ته ووئيل، ”تۀ به هيڅکله دننه نۀ شې راتلے، ړاندۀ او شل دې هم بهر ايسارولے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7628, '2 Samuel 5:7', '2 Samuel', 5, 7, '&nbsp;خو داؤد د هغوئ د صيون قلعه قبضه کړه او دا ”د داؤد ښار“ په نوم مشهوره شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7629, '2 Samuel 5:8', '2 Samuel', 5, 8, '&nbsp;په هغه ورځ داؤد خپلو سړو ته ووئيل، ”دلته داسې څوک شته چې هغه د يبوسيانو سره زما هومره نفرت لرى؟ دومره زيات چې هغوئ ووژنى؟ نو د اوبو په سورنګ کښې لاړ شئ او په هغه غريبو، شلو او ړندو باندې حمله وکړئ.“ نو داسې دا يو متل جوړ شو، ”شل او ړاندۀ د مالِک خُدائ کور ته نۀ شى ننوتلے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7630, '2 Samuel 5:9', '2 Samuel', 5, 9, '&nbsp;د هغه قلعې قبضه کولو نه پس، داؤد په دې کښې اوسېدو او ”د داؤد ښار“ نوم يې پرې کېښودو. هغۀ د دې نه ګېرچاپېره ښار جوړ کړو، د هغه ځائ نه يې شروع وکړه چرته چې د غرۀ نمرخاتۀ طرف ته زمکه په خاورو باندې ډکه شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7631, '2 Samuel 5:10', '2 Samuel', 5, 10, '&nbsp;هغه وخت په وخت نور هم تکړه کېدو، ځکه چې مالِک خُدائ ربُ الافواج د هغۀ مل وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7632, '2 Samuel 5:11', '2 Samuel', 5, 11, '&nbsp;د صور بادشاه حيرام داؤد ته يو کاروبارى ډله ولېږله، هغۀ له يې د ترکاڼانو سره د نختر لرګى او د کاڼو ګِلکاران ورکړل چې يو محل جوړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7633, '2 Samuel 5:12', '2 Samuel', 5, 12, '&nbsp;نو داؤد ته پته ولګېده چې مالِک خُدائ دے د بنى اِسرائيلو بادشاه مقرر کړے دے او د خپلو خلقو د خاطره يې خپله بادشاهى بختوره کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7634, '2 Samuel 5:13', '2 Samuel', 5, 13, '&nbsp;د حبرون نه يروشلم ته تلو نه پس، داؤد نورې وينځې او ښځې وکړې او نور زامن او لوڼه يې پېدا شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7635, '2 Samuel 5:14', '2 Samuel', 5, 14, '&nbsp;د هغۀ دا بچى په يروشلم کښې پېدا شوى وُو يعنې، سموع، سوباب، ناتن، سليمان،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7636, '2 Samuel 5:15', '2 Samuel', 5, 15, '&nbsp;اِبحار، اليسوع، نفج، يفيع،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7637, '2 Samuel 5:16', '2 Samuel', 5, 16, '&nbsp;اليسمع، اليدع او اليفلط.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7638, '2 Samuel 5:17', '2 Samuel', 5, 17, '&nbsp;کله چې فلستيان خبر شول چې داؤد د بنى اِسرائيلو بادشاه جوړ شوے دے، نو د هغوئ ټول لښکر روان شو چې داؤد ونيسى. کله چې داؤد د دې نه خبر شو نو هغه لاندې د پَخو دېوالونو ځائ ته لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7639, '2 Samuel 5:18', '2 Samuel', 5, 18, '&nbsp;فلستيان د رفائيم وادۍ ته راروسېدل او دا يې قبضه کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7640, '2 Samuel 5:19', '2 Samuel', 5, 19, '&nbsp;داؤد د مالِک خُدائ نه تپوس وکړو، ”زۀ په فلستيانو حمله وکړم څۀ؟ تۀ به ما له فتح راکړې څۀ؟“ مالِک خُدائ ورته وفرمائيل، ”آو، حمله پرې وکړه، زۀ به تا له فتح درکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7641, '2 Samuel 5:20', '2 Samuel', 5, 20, '&nbsp;نو داؤد بعل‌پراضيم ته لاړو او هلته يې فلستيانو له شکست ورکړو. هغۀ وفرمائيل، ”مالِک خُدائ زما د دشمنانو نه د سېلاب په شان ناڅاپه تېر شوے دے.“ نو د هغه ځائ نوم بعل‌پراضيم شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7642, '2 Samuel 5:21', '2 Samuel', 5, 21, '&nbsp;کله چې فلستيان وتښتېدل، نو هغوئ خپل بُتان شا ته پرېښودل او داؤد او د هغۀ سړو دا يوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7643, '2 Samuel 5:22', '2 Samuel', 5, 22, '&nbsp;فلستيان واپس د رفائيم وادۍ ته لاړل او دا يې بيا قبضه کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7644, '2 Samuel 5:23', '2 Samuel', 5, 23, '&nbsp;داؤد يو ځل بيا د مالِک خُدائ سره مشوره وکړه او هغۀ ورته وفرمائيل، ”په هغوئ د دې ځائ نه حمله مۀ کوه، خو د بل طرف نه ورباندې راتاو شه او حمله پرې وکړه، چرته چې د تُوت ونې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7645, '2 Samuel 5:24', '2 Samuel', 5, 24, '&nbsp;کله چې تۀ د تُوت د ونو په سرونو د تګ آواز واورې، نو بيا حمله وکړه، زۀ به ستاسو نه مخکښې روان يم د دې دپاره چې د فلستيانو لښکر له شکست ورکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7646, '2 Samuel 5:25', '2 Samuel', 5, 25, '&nbsp;داؤد هم هغه شان وکړل چې څنګه مالِک خُدائ حُکم کړے وو او فلستيان يې د جبعې نه تر جزر پورې قتل کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7647, '2 Samuel 6:1', '2 Samuel', 6, 1, '&nbsp;داؤد يو ځل بيا د بنى اِسرائيلو ښۀ فوجيان راغونډ کړل چې ټول دېرش زره سړى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7648, '2 Samuel 6:2', '2 Samuel', 6, 2, '&nbsp;او هغوئ يې په يهوداه کښې بعله ته بوتلل، چې د هغه ځائ نه د خُدائ پاک د لوظ صندوق راوړى چې دا صندوق د ربُ الافواج په نوم ياديږى، چې هغه د وزرو والا مخلوق په مينځ کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7649, '2 Samuel 6:3', '2 Samuel', 6, 3, '&nbsp;هغوئ دا په غرۀ باندې د ابينداب د کور نه واخستو او په يوه نوې ګاډۍ باندې يې کېښودو. د ابينداب زامنو عُزه او اخيو ګاډۍ روانه کړې وه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7650, '2 Samuel 6:4', '2 Samuel', 6, 4, '&nbsp;اخيو ورسره مخکښې روان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7651, '2 Samuel 6:5', '2 Samuel', 6, 5, '&nbsp;داؤد او ټول بنى اِسرائيليان ګډېدل او د خپل ټول طاقت سره د مالِک خُدائ د درناوى دپاره يې حمد‌و‌ثناء وئيله. هغوئ بينجو، رباب، تمبل، چمټې او د ساز لوښى غږول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7652, '2 Samuel 6:6', '2 Samuel', 6, 6, '&nbsp;کله چې هغوئ د نکون درمند ته راغلل، نو غوَيى په غورزېدو شو او عُزه وروړاندې شو او د لوظ صندوق يې قابو کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7653, '2 Samuel 6:7', '2 Samuel', 6, 7, '&nbsp;مالِک خُدائ، خُدائ پاک سمدستى عُزه ته په قهر شو او وې وژلو ځکه چې هغۀ په بې‌ادبۍ سره د لوظ صندوق له لاس وروړے وو. عُزه د لوظ صندوق په خوا کښې مړ شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7654, '2 Samuel 6:8', '2 Samuel', 6, 8, '&nbsp;نو تر ننه پورې د هغه ځائ نوم فارص‌عُزه دے. داؤد سخت خفه وو ځکه چې مالِک خُدائ په غصه کښې عُزه له سزا ورکړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7655, '2 Samuel 6:9', '2 Samuel', 6, 9, '&nbsp;داؤد د مالِک خُدائ نه ويرېدو او وې فرمائيل، ”زۀ اوس د لوظ صندوق ځان سره واپس څنګه يوسم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7656, '2 Samuel 6:10', '2 Samuel', 6, 10, '&nbsp;نو هغۀ دا فېصله وکړه چې هغه به دا د ځان سره يروشلم ته نۀ وړى، نو هغه د لارې نه واوړېدو او صندوق يې د عوبيد ادوم کور ته يوړو، چې هغه د جات د ښار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7657, '2 Samuel 6:11', '2 Samuel', 6, 11, '&nbsp;هغه درې مياشتې هلته پروت وو او مالِک خُدائ عوبيد ادوم او د هغۀ خاندان له برکت ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7658, '2 Samuel 6:12', '2 Samuel', 6, 12, '&nbsp;داؤد بادشاه خبر شو چې مالِک خُدائ د لوظ صندوق په وجه د عوبيد ادوم خاندان او د هغۀ هر څۀ له برکت ورکړے دے، نو هغۀ د عوبيد ادوم د کور نه د لوظ صندوق واخستلو چې د يو لوئ جشن سره يې يروشلم ته يوسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7659, '2 Samuel 6:13', '2 Samuel', 6, 13, '&nbsp;کومو سړو چې د لوظ صندوق وړلو هغه يو شپږ قدمه تلى وُو، داؤد هغوئ ودرول او په دې دوران کښې هغۀ مالِک خُدائ ته د يو غوَيى او د يو څورب سخى قربانى پېش کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7660, '2 Samuel 6:14', '2 Samuel', 6, 14, '&nbsp;داؤد صِرف د لټې يو پېش بند اغوستے وو او د خپل ټول طاقت سره د مالِک خُدائ د درناوى دپاره ګډېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7661, '2 Samuel 6:15', '2 Samuel', 6, 15, '&nbsp;نو هغۀ او ټولو بنى اِسرائيلو د چغو او د بيګل د آوازونو سره د لوظ صندوق يروشلم ته يوړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7662, '2 Samuel 6:16', '2 Samuel', 6, 16, '&nbsp;کله چې د لوظ صندوق ښار ته راروان وو، نو د ساؤل لور ميکل د کړکۍ نه بهر وکتل او وې ليدل چې داؤد بادشاه د مالِک خُدائ په وړاندې ګډيږى او ټوپونه وهى، نو هغې ته هغه سپک ښکاره شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7663, '2 Samuel 6:17', '2 Samuel', 6, 17, '&nbsp;هغوئ د مالِک خُدائ صندوق راوړو او په خېمه کښې يې په خپل ځائ باندې کېښودو چې داؤد ورله جوړ کړے وو. بيا هغۀ مالِک خُدائ ته سوزېدونکې نذرانې او د سلامتۍ نذرانې پېش کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7664, '2 Samuel 6:18', '2 Samuel', 6, 18, '&nbsp;کله چې هغۀ قربانۍ پېش کول ختم کړل نو هغۀ د ربُ الافواج په نوم باندې خلقو له برکت ورکړو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7665, '2 Samuel 6:19', '2 Samuel', 6, 19, '&nbsp;او په ټولو باندې يې خوراک تقسيم کړو. هغۀ د بنى اِسرائيلو هر يو سړى او ښځې له يوه يوه غټه ډوډۍ، څۀ کجورې او څۀ کشمش ورکړل. بيا هر يو کس کور ته لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7666, '2 Samuel 6:20', '2 Samuel', 6, 20, '&nbsp;کله چې داؤد خپل کور ته لاړو چې خپل خاندان له مبارکى ورکړى، نو ميکل مِلاوېدو دپاره ورله راووتله. هغې ووئيل، ”د بنى اِسرائيلو بادشاه خو نن د ځان ښۀ درناوے کړے دے. هغۀ د خپلو درباريانو د وينځو په مخکښې د ليونى په شان خپل ځان بې‌پردې کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7667, '2 Samuel 6:21', '2 Samuel', 6, 21, '&nbsp;داؤد ورته وفرمائيل، ”زۀ د مالِک خُدائ په مخکښې ګډېږم، چې هغۀ ستا د پلار او د هغۀ د خاندان په ځائ زۀ خوښ کړم او د خپلو بنى اِسرائيلو مشر يې جوړ کړم. نو ځکه زۀ به د مالِک خُدائ د درناوى دپاره ګډېږم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7668, '2 Samuel 6:22', '2 Samuel', 6, 22, '&nbsp;او زۀ به خپل ځان نور هم سپکوم. ستا خيال به دا وى چې زۀ هيڅ هم نۀ يم، خو د دې وينځو په خيال کښې به زۀ دروند يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7669, '2 Samuel 6:23', '2 Samuel', 6, 23, '&nbsp;نو د ساؤل د لور ميکل، تر مرګه پورې بچى نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7670, '2 Samuel 7:1', '2 Samuel', 7, 1, '&nbsp;داؤد بادشاه په سکون سره خپل محل کښې اوسېدو او مالِک خُدائ هغه د خپلو ټولو دشمنانو نه بې‌غمه کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7671, '2 Samuel 7:2', '2 Samuel', 7, 2, '&nbsp;يوه ورځ داؤد بادشاه ناتن پېغمبر ته وفرمائيل، ”زۀ دلته په يو داسې کور کښې اوسېږم چې د دِيار د ونې نه جوړ دے، خو د خُدائ پاک د لوظ صندوق په يوه خېمه کښې پروت دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7672, '2 Samuel 7:3', '2 Samuel', 7, 3, '&nbsp;ناتن ورته وفرمائيل، ”چې څۀ دې په زړۀ کښې وى نو هم هغه شان وکړه، ځکه چې مالِک خُدائ ستا مل دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7673, '2 Samuel 7:4', '2 Samuel', 7, 4, '&nbsp;خو په هغه شپه د مالِک خُدائ کلام په ناتن نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7674, '2 Samuel 7:5', '2 Samuel', 7, 5, '&nbsp;”لاړ شه او زما خِدمت کوونکى داؤد ته ووايه چې زۀ داسې وايم چې تۀ هغه څوک نۀ يې چې زما دپاره د اوسېدو دپاره کور جوړ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7675, '2 Samuel 7:6', '2 Samuel', 7, 6, '&nbsp;د هغه وخت نه واخله چې ما بنى اِسرائيل د مِصر نه راوويستل تر اوسه پورې زۀ کله هم په يو کور کښې نۀ يم اوسېدلے، ما د هغوئ سره سفر کولو او په يوه خېمه کښې اوسېدم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7676, '2 Samuel 7:7', '2 Samuel', 7, 7, '&nbsp;د بنى اِسرائيلو سره په ټول سفر کښې ما د هغوئ مشرانو کښې يو ته هم نۀ دى وئيلى چې زما دپاره تاسو د دِيار کور ولې نۀ دے جوړ کړے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7677, '2 Samuel 7:8', '2 Samuel', 7, 8, '&nbsp;نو زما خِدمت کوونکى داؤد ته ووايه چې زۀ ربُ الافواج هغۀ ته وايم چې ما تۀ په پټو کښې د ګډو شپونتوب نه بوتلې او د خپلو خلقو بنى اِسرائيلو بادشاه مې جوړ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7678, '2 Samuel 7:9', '2 Samuel', 7, 9, '&nbsp;تۀ چې چرته هم تلې نو زۀ ستا مل وم او چې تۀ مخ په وړاندې تلې نو ما ستا ټولو دشمنانو له شکست ورکولو. زۀ به ستا نوم د دُنيا د لويو مشرانو په شان مشهور کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7679, '2 Samuel 7:12', '2 Samuel', 7, 12, '&nbsp;کله چې تۀ مړ شې او د خپل پلار نيکۀ په اديره کښې ښخ شې، نو زۀ به ستا يو زوئ بادشاه جوړ کړم او د هغۀ بادشاهى به قائمه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7680, '2 Samuel 7:13', '2 Samuel', 7, 13, '&nbsp;نو هغه به زما د نوم دپاره کور جوړ کړى او د هغۀ بادشاهى به د همېشه دپاره قائمه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7681, '2 Samuel 7:14', '2 Samuel', 7, 14, '&nbsp;زۀ به د هغۀ د پلار په شان يم او هغه به زما د زوئ په شان وى. کله چې هغه غلطى وکړى نو زۀ به هغۀ له د يو انسانى پلار په شان په چُوکه سزا ورکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7682, '2 Samuel 7:15', '2 Samuel', 7, 15, '&nbsp;خو زۀ به د هغۀ نه خپله نۀ ختمېدونکې مينه نۀ لرې کوم لکه څنګه چې ما د ساؤل نه لرې کړه، هغه مې د دې دپاره اخوا کړو چې تۀ بادشاه شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7683, '2 Samuel 7:16', '2 Samuel', 7, 16, '&nbsp;تۀ به همېشه اولاد لرې او زۀ به ستا بادشاهى تل دپاره قائمه ساتم. ستا بادشاهت به هيڅکله نه ختميږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7684, '2 Samuel 7:17', '2 Samuel', 7, 17, '&nbsp;ناتن داؤد ته هغه ټولې خبرې وکړې چې خُدائ پاک په هغۀ نازلې کړې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7685, '2 Samuel 7:18', '2 Samuel', 7, 18, '&nbsp;بيا داؤد د مالِک خُدائ د حضور خېمې ته دننه لاړو، کښېناستو او دُعا يې وکړه، ”مالِکه خُدايه، خُدايه پاکه، زۀ او زما خاندان د دې لائق نۀ يُو، څۀ چې تا زمونږ دپاره کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7686, '2 Samuel 7:19', '2 Samuel', 7, 19, '&nbsp;مالِکه خُدايه پاکه، او بيا تا د نور څۀ کولو وعده هم کړې ده. مالِکه خُدايه پاکه، تۀ اکثر د خلقو سره هم دغه شان کوې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7687, '2 Samuel 7:20', '2 Samuel', 7, 20, '&nbsp;زۀ نور تا ته څۀ ووايم. تۀ ما خپل خِدمت کوونکے پېژنې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7688, '2 Samuel 7:21', '2 Samuel', 7, 21, '&nbsp;د خپلې وعدې د خاطره او د خپلې مرضۍ په مطابق، تا دا لوئ کار کړے دے او دا دې خپل خِدمت کوونکى ته ښودلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7689, '2 Samuel 7:22', '2 Samuel', 7, 22, '&nbsp;مالِکه خُدايه پاکه، تۀ څومره لوئ يې، ستا په شان بل هيڅ څوک هم نشته، مونږ ته همېشه دا پته ده چې صِرف تۀ خُدائ پاک يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7690, '2 Samuel 7:23', '2 Samuel', 7, 23, '&nbsp;د زمکې په مخ باندې د بنى اِسرائيلو په شان بل يو قوم هم نشته، چې هغوئ تا د غلامۍ نه خلاص کړل د دې دپاره چې هغوئ ستا خپل خلق شى. تا چې د هغوئ دپاره کوم لوئ او عجيبه کارونه کړى دى د هغې په وجه ستا نوم په دُنيا کښې مشهور او خور شوے دے. چې ستا خلق مخ په وړاندې تلل نو تا نور قومونه او د هغوئ معبودان لرې کړل، هغه خلق کوم چې تا د مِصر نه آزاد کړل د دې دپاره چې ستا خپل خلق شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7691, '2 Samuel 7:24', '2 Samuel', 7, 24, '&nbsp;تا بنى اِسرائيليان همېشه دپاره خپل خلق جوړ کړى دى او مالِکه خُدايه، تۀ د هغوئ خُدائ پاک شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7692, '2 Samuel 7:25', '2 Samuel', 7, 25, '&nbsp;نو مالِکه خُدايه پاکه، تۀ خپله وعده پوره کوه، کومه وعده چې تا زما او زما د اولاد په حقله کړې ده او چې تا څۀ فرمائيلى دى هم هغه وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7693, '2 Samuel 7:26', '2 Samuel', 7, 26, '&nbsp;ستا نوم به لوئ وى او خلق به همېشه وائى چې، ربُ الافواج د بنى اِسرائيلو خُدائ پاک دے. او ستا د خِدمت کوونکى داؤد بادشاهت به د همېشه دپاره قائم وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7694, '2 Samuel 7:27', '2 Samuel', 7, 27, '&nbsp;ربُ الافواجه، د بنى اِسرائيلو خُدايه پاکه، زۀ دا جرأت کوم چې زۀ ستا نه دا سوال وکړم، ځکه چې تا دا هر څۀ په ما، په خپل خِدمت کوونکى نازل کړى دى او تا ما ته فرمائيلى دى چې تۀ به زما د اولاد نه بادشاهان جوړوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7695, '2 Samuel 7:28', '2 Samuel', 7, 28, '&nbsp;نو مالِکه خُدايه، هم تۀ خُدائ پاک يې، ستا کلام رښتونے دے او تا زما سره دا زبردسته وعده کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7696, '2 Samuel 7:29', '2 Samuel', 7, 29, '&nbsp;زۀ تا ته سوال کوم چې تۀ زما اولاد له برکت ورکړه نو چې هغوئ ستا د رحم نه خوند واخلى. مالِکه خُدايه پاکه، تا دا وعده کړې ده او ستا برکت به تل دپاره زما د اولاد په سر وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7697, '2 Samuel 8:1', '2 Samuel', 8, 1, '&nbsp;څۀ وخت وروستو داؤد بادشاه فلستيانو له شکست ورکړو. نو بنى اِسرائيليان د هغوئ د قبضې نه خلاص شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7698, '2 Samuel 8:2', '2 Samuel', 8, 2, '&nbsp;بيا هغۀ موآبيانو له شکست ورکړو. هغۀ قېديان په قطار کښې په زمکه څملول او قبيلې يې جوړې کړې. د هرو درېو ډلو نه به يې دوه قتلولې او يوه به يې ژوندۍ پرېښودله. نو موآبيان د هغۀ د اختيار لاندې راغلل او هغۀ له يې محصُول ورکولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7699, '2 Samuel 8:3', '2 Samuel', 8, 3, '&nbsp;بيا داؤد د شام د مُلک د ضوباه بادشاه له شکست ورکړو، چې د هغۀ نوم هدد‌عزر وو او دې د رِحوب زوئ وو، دا په هغه وخت کښې وشول چې کله هدد‌عزر د پاسنى فرات سره علاقې بيا نيولو له روان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7700, '2 Samuel 8:4', '2 Samuel', 8, 4, '&nbsp;داؤد د هغۀ اوولس سوه په آسونو سوارۀ سړى او شل زره عام فوجيان ونيول. هغۀ د سلو جنګى ګاډو دپاره ښۀ ډېر آسونه وساتل او باقى نور ټول يې ګوډ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');